package net.civeira.phylax.feature.observe.observedembed.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowRawVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allow raw of observed embed ")
  void test_allow_raw_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AllowRawVO.tryFrom(null));
    Assertions.assertEquals(true, AllowRawVO.from(true).isAllowRaw());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AllowRawVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", AllowRawVO.from(true).toString());
  }
}
